#!/usr/bin/env node
/**
 * ios-bundle-guard — make the iOS runtime config a BUNDLED-assets config, and
 * prove it.
 *
 * Android ships as a thin shell: capacitor.config.json sets
 * `server.url = https://moathdarweesh.github.io/vault/`, so the APK loads the
 * live site and a push updates every install. iOS cannot ship that way — App
 * Store Review Guideline 4.2 rejects "a web site bundled as an app", and a
 * WKWebView pointed at a remote URL is the shape reviewers apply it to.
 *
 * `ios/App/App/capacitor.config.json` is GITIGNORED and regenerated by every
 * `cap sync`, so this cannot be fixed once and committed. It has to run after
 * every sync — locally through `npm run sync:ios`, and in CI as its own step.
 *
 * This file does one job so that its failure is legible: it does not build and
 * it does not sync. Run it after `npx cap sync ios`.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const CONFIG = path.join(root, 'ios', 'App', 'App', 'capacitor.config.json');
const BUNDLE = path.join(root, 'ios', 'App', 'App', 'public', 'index.html');

function die(msg) {
  console.error('ios-bundle-guard: ' + msg);
  process.exit(1);
}

if (!fs.existsSync(CONFIG)) die('no ' + path.relative(root, CONFIG) + ' — run `npx cap sync ios` first.');

let cfg;
try { cfg = JSON.parse(fs.readFileSync(CONFIG, 'utf8')); }
catch (e) { die('could not parse the iOS config: ' + e.message); }

const had = !!(cfg.server && cfg.server.url);
delete cfg.server;
delete cfg.android;   // meaningless in the iOS runtime config, and only confusing
fs.writeFileSync(CONFIG, JSON.stringify(cfg, null, '\t') + '\n');

// Re-read from disk. Proving the write, not the intention — the whole App Store
// question turns on this one absence.
let after;
try { after = JSON.parse(fs.readFileSync(CONFIG, 'utf8')); }
catch (e) { die('the config I just wrote does not parse: ' + e.message); }

if (after.server) die('FAILED — `server` survived. Do not build this.');
if (!after.appId) die('FAILED — the config lost appId.');
if (!after.webDir) die('FAILED — the config lost webDir.');
if (!fs.existsSync(BUNDLE)) die('FAILED — no bundled index.html at ios/App/App/public. The app would open blank.');

console.log('ios-bundle-guard: ok');
console.log('  server block ' + (had ? 'REMOVED (it was the live URL)' : 'was already absent'));
console.log('  appId ' + after.appId + ' · webDir ' + after.webDir);
console.log('  bundled entry: ' + path.relative(root, BUNDLE));
